export const SAMPLE_RATE=48e3,cancelled=()=>new DOMException("Simulation preparation cancelled.","AbortError");export function check(l){if(l?.aborted)throw cancelled()}const M=48e3,x=Math.PI*2;function P(l){let e=l>>>0||1;return()=>{e|=0,e=e+1831565813|0;let s=Math.imul(e^e>>>15,1|e);return s=s+Math.imul(s^s>>>7,61|s)^s,((s^s>>>14)>>>0)/4294967296}}function E(l,e,s,d,w,r="sine"){const m=Math.round(e*M),h=Math.round(s*M),c=l.length;let u=0;for(let f=0;f<h;f++){const t=f/h,n=Math.min(1,f/(M*.004))*(1-t)**2.2;u+=d/M;const a=r==="tri"?1-4*Math.abs(u%1-.5):Math.sin(u*x);l[(m+f)%c]+=w*n*a}}export async function synthesize(l,e,s,{signal:d}={}){if(check(d),e.sound==="off"||e.volume===0)return null;const w=Math.round(l*M),r=new Float32Array(w),m=e.volume/100*.8,h=s.turns,c=l,u=e.sound,f=t=>Math.max(1,Math.round(t*c))/c;if(u==="hum"){const t=f(110),n=f(110.6),a=f(165),i=h/c;for(let o=0;o<w;o++){(o&65535)===0&&(await new Promise(y=>setTimeout(y,0)),check(d));const p=o/M,A=.6+.4*Math.sin(x*i*p);r[o]=m*.16*A*(Math.sin(x*t*p)+.8*Math.sin(x*n*p)+.35*Math.sin(x*a*p)*(.5+.5*Math.cos(x*i*p)))}}else if(u==="whoosh"){const t=P(e.seed+11);let n=0,a=0;const i=c/h/2;for(let o=0;o<w;o++){(o&65535)===0&&(await new Promise(b=>setTimeout(b,0)),check(d));const p=o/M,A=p%i/i,y=Math.sin(Math.PI*A)**3,T=t()*2-1;n+=.08*(T-n),a+=.3*(n-a),r[o]=m*.9*y*a}}else if(u==="ticks"){const t=c/h/8;for(let n=0;n<h*8;n++)E(r,n*t,.06,n%8===0?1760:1320,m*.35,"sine")}else if(u==="chimes"){const t=[523.25,587.33,659.25,783.99,880,1046.5],n=P(e.seed+5),a=c/h/4;for(let i=0;i<h*4;i++){const o=t[Math.floor(n()*t.length)];E(r,i*a,.9,o,m*.22,"sine"),E(r,i*a,.6,o*2,m*.05,"sine")}}check(d);for(let t=0;t<w;t++)r[t]=Math.tanh(r[t]*1.3);return{samples:r,sampleRate:M}}
